"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "edge",
    "name": "api-gateway",
    "uid": "uid-deployment-api-gateway"
  },
  "params": {
    "container": "app",
    "liveness": {
      "initialDelaySeconds": 90,
      "timeoutSeconds": 10
    }
  },
  "expected_effect": "Allow 60s+ for route loading before liveness probe kills the container",
  "rationale": "Container logs show route reload takes ~60s (\"expect about 60s before listening\") and the Notice event explicitly requests 90s initial delay. Current liveness probe (10s delay, 1s timeout) kills the container before it's ready. Increasing delay to 90s and timeout to 10s aligns with observed startup time.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-pod_states", "ev-target_events", "ev-container_logs_tail"],
  "cited_predicates": ["killed_during_startup", "probe_kills", "probe_timeouts"]
}
}
